('29aa63c0-8d30-40ba-a379-21a05d6c2339', 'sentence_completion', 'The auditor''s report was notable for its ___ , addressing even the most minor financial discrepancies.', NULL, '[{"id": "a", "text": "thoroughness"}, {"id": "b", "text": "brevity"}, {"id": "d", "text": "superficiality"}, {"id": "c", "text": "vagueness"}]'::jsonb, 0, '{"strategy": "addressing even the most minor discrepancies = מתייחס אפילו לאי-התאמות הקטנות ביותר. איזה דוח עושה זאת?", "correct_reason": "thoroughness = יסודיות. דוח שמתייחס לפרטים הקטנים ביותר הוא יסודי.", "options_analysis": ["נכון! thoroughness = יסודיות — מתאימה להתייחסות לפרטים הקטנים ביותר", "brevity = תמציתיות — הפוך מהתייחסות מפורטת לפרטים", "superficiality = שטחיות — הפוך מהתייחסות לפרטים קטנים", "vagueness = מעורפלות — הפוך מהתייחסות לפרטים קטנים"]}', 1.82, 1.0, 0.25, 4, 'ai', NULL, true),
('b4fe95a1-9a52-4c44-93c3-65ab83519f36', 'sentence_completion', 'The panel''s decision to postpone the vote was widely interpreted as a sign of internal ___.', NULL, '[{"id": "d", "text": "consensus"}, {"id": "c", "text": "discord"}, {"id": "b", "text": "agreement"}, {"id": "a", "text": "unity"}]'::jsonb, 1, '{"strategy": "widely interpreted as = פורש באופן נרחב כ-. מה מרמזת דחיית הצבעה על מצב פנימי?", "correct_reason": "discord = אי-הסכמה/מחלוקת. דחיית הצבעה בדרך כלל מרמזת על חוסר הסכמה פנימי.", "options_analysis": ["consensus = הסכמה כללית — הפוך ממה שדחיית הצבעה מרמזת", "נכון! discord = מחלוקת — מתאים לפרשנות של דחיית הצבעה", "agreement = הסכמה — הפוך ממה שדחיית הצבעה מרמזת", "unity = אחדות — הפוך ממה שדחיית הצבעה מרמזת עליו"]}', 1.58, 1.0, 0.25, 4, 'ai', NULL, true),
('64444c00-2271-4a86-a7dd-107416acf337', 'sentence_completion', 'The critic praised the film''s ___ pacing, noting that it never felt rushed or dragged out.', NULL, '[{"id": "a", "text": "inconsistent"}, {"id": "c", "text": "frantic"}, {"id": "b", "text": "measured"}, {"id": "d", "text": "erratic"}]'::jsonb, 2, '{"strategy": "never felt rushed or dragged out = לא הרגיש ממהר או נמשך. איזה קצב לא ממהר ולא נמשך?", "correct_reason": "measured = מדוד/מאוזן. קצב מדוד לא נתפס כממהר ולא כנמשך.", "options_analysis": ["inconsistent = לא עקבי — הפוך מקצב מאוזן", "frantic = קדחתני — הפוך מקצב שלא הרגיש ממהר", "נכון! measured = מדוד — מתאים לקצב מאוזן שלא נתפס כקיצוני בשני הכיוונים", "erratic = לא יציב — הפוך מקצב שלא הרגיש ממהר או נמשך"]}', 1.37, 1.0, 0.25, 4, 'ai', NULL, true),
('c40b35f2-f717-4978-8847-362316a2c5f9', 'sentence_completion', 'The politician''s refusal to answer direct questions only served to ___ suspicions about her involvement.', NULL, '[{"id": "b", "text": "dispel"}, {"id": "a", "text": "eliminate"}, {"id": "c", "text": "calm"}, {"id": "d", "text": "heighten"}]'::jsonb, 3, '{"strategy": "refusal to answer...only served to = סירוב לענות...רק שירת ל-. מה עושה סירוב לענות לחשדות?", "correct_reason": "heighten = להעצים. סירוב לענות על שאלות ישירות מעצים חשדות.", "options_analysis": ["dispel = לפזר — הפוך מהשפעת סירוב לענות", "eliminate = לחסל — הפוך מהשפעת סירוב לענות", "calm = להרגיע — הפוך מהשפעת סירוב לענות", "נכון! heighten = להעצים — מתאים להשפעת סירוב לענות על חשדות"]}', 1.5, 1.0, 0.25, 4, 'ai', NULL, true),
('c44524d6-05c3-42c2-9828-59afcfeb3e55', 'sentence_completion', 'The professor''s willingness to admit uncertainty, rather than feign expertise, was seen as a mark of intellectual ___.', NULL, '[{"id": "a", "text": "humility"}, {"id": "c", "text": "ignorance"}, {"id": "b", "text": "deceit"}, {"id": "d", "text": "arrogance"}]'::jsonb, 0, '{"strategy": "rather than feign expertise = במקום להעמיד פנים כמומחה. מה מעידה נכונות להודות באי-ודאות?", "correct_reason": "humility = ענווה. נכונות להודות באי-ודאות במקום להעמיד פנים מעידה על ענווה.", "options_analysis": ["נכון! humility = ענווה — מתאימה לנכונות להודות באי-ודאות", "ignorance = בורות — לא מתאר את התכונה החיובית שהפגין הפרופסור", "deceit = רמאות — הפוך מכנות והודאה באי-ודאות", "arrogance = יהירות — הפוך מנכונות להודות באי-ודאות"]}', 1.61, 1.0, 0.25, 4, 'ai', NULL, true),
('e29945c4-119f-4700-aacb-b7e909b824c4', 'sentence_completion', 'The report''s conclusions, though presented with great confidence, were based on data that many experts consider ___.', NULL, '[{"id": "a", "text": "conclusive"}, {"id": "d", "text": "unreliable"}, {"id": "b", "text": "robust"}, {"id": "c", "text": "comprehensive"}]'::jsonb, 1, '{"strategy": "though presented with confidence, based on data many consider = למרות הצגה בביטחון, מבוסס על נתונים שרבים רואים. ניגוד.", "correct_reason": "unreliable = לא אמינים. ביטחון בהצגה שסותר דעת מומחים על אמינות הנתונים.", "options_analysis": ["conclusive = חד-משמעיים — הפוך מהניגוד הנדרש", "נכון! unreliable = לא אמינים — יוצר ניגוד הגיוני עם הביטחון בהצגה", "robust = איתנים — הפוך מהניגוד ל''though presented with great confidence''", "comprehensive = מקיפים — לא יוצר את הניגוד הנדרש"]}', 1.78, 1.0, 0.25, 4, 'ai', NULL, true),
('c4eb508f-0e24-4a8f-a1c9-0d51139f5ca5', 'sentence_completion', 'The startup''s founders were praised for their ___ approach, adapting quickly to setbacks rather than clinging to a fixed plan.', NULL, '[{"id": "b", "text": "stubborn"}, {"id": "d", "text": "rigid"}, {"id": "a", "text": "adaptive"}, {"id": "c", "text": "inflexible"}]'::jsonb, 2, '{"strategy": "adapting quickly to setbacks rather than clinging to fixed plan = מסתגלים מהר במקום להיצמד לתוכנית קבועה. איזו גישה מתארת זאת?", "correct_reason": "adaptive = מסתגל. גישה שמסתגלת מהר לבעיות היא אדפטיבית.", "options_analysis": ["stubborn = עקשן — הפוך מהסתגלות מהירה", "rigid = נוקשה — הפוך מהסתגלות מהירה", "נכון! adaptive = מסתגל — מתאים להסתגלות מהירה לבעיות", "inflexible = לא גמיש — הפוך מהסתגלות מהירה"]}', 1.51, 1.0, 0.25, 4, 'ai', NULL, true),
('b33bf6bf-2176-451e-85bd-ffd71ebc94fe', 'sentence_completion', 'The negotiator''s ___ demeanor throughout the tense talks helped prevent the discussions from breaking down entirely.', NULL, '[{"id": "c", "text": "erratic"}, {"id": "d", "text": "agitated"}, {"id": "b", "text": "volatile"}, {"id": "a", "text": "unflappable"}]'::jsonb, 3, '{"strategy": "helped prevent the discussions from breaking down = עזרה למנוע קריסת הדיונים. איזו התנהגות תחת לחץ מונעת קריסה?", "correct_reason": "unflappable = לא מתרגש/קר רוח. התנהגות קרת רוח תחת לחץ מונעת קריסת דיונים.", "options_analysis": ["erratic = לא יציב — הפוך מהתנהגות שמונעת קריסה", "agitated = נסער — הפוך מהתנהגות שמונעת קריסה", "volatile = תנודתי — הפוך מהתנהגות שמונעת קריסה", "נכון! unflappable = קר רוח — מתאים למניעת קריסת דיונים תחת לחץ"]}', 1.68, 1.0, 0.25, 4, 'ai', NULL, true),
('e07ccf8e-b192-4cd6-9cad-94fa93a41e9d', 'sentence_completion', 'The documentary''s ___ portrayal of the crisis avoided the exaggeration common in similar films.', NULL, '[{"id": "c", "text": "measured"}, {"id": "a", "text": "dramatic"}, {"id": "d", "text": "sensationalized"}, {"id": "b", "text": "exaggerated"}]'::jsonb, 0, '{"strategy": "avoided the exaggeration common in similar films = נמנע מההגזמה הנפוצה. איזה תיאור נמנע מהגזמה?", "correct_reason": "measured = מדוד/מאוזן. תיאור מדוד נמנע מהגזמה.", "options_analysis": ["נכון! measured = מדוד — מתאים להימנעות מהגזמה", "dramatic = דרמטי — לא בהכרח נמנע מהגזמה", "sensationalized = מוגזם/סנסציוני — הפוך מהימנעות מהגזמה", "exaggerated = מוגזם — הפוך מהימנעות מהגזמה"]}', 1.7, 1.0, 0.25, 4, 'ai', NULL, true),
('1b641c40-5b73-47ee-9fff-1f157b298f66', 'sentence_completion', 'The board''s ___ handling of the merger negotiations ultimately secured favorable terms for shareholders.', NULL, '[{"id": "c", "text": "careless"}, {"id": "a", "text": "adept"}, {"id": "d", "text": "inept"}, {"id": "b", "text": "clumsy"}]'::jsonb, 1, '{"strategy": "ultimately secured favorable terms = בסופו של דבר השיגה תנאים נוחים. איזה טיפול במשא ומתן משיג תנאים טובים?", "correct_reason": "adept = מיומן. טיפול מיומן במשא ומתן משיג תנאים נוחים.", "options_analysis": ["careless = חסר זהירות — הפוך מהשגת תנאים נוחים", "נכון! adept = מיומן — מתאים להשגת תנאים נוחים בהצלחה", "inept = חסר יכולת — הפוך מהשגת תנאים נוחים", "clumsy = מסורבל — הפוך מהשגת תנאים נוחים"]}', 1.76, 1.0, 0.25, 4, 'ai', NULL, true),
('52484c1a-e266-483d-abee-84e417c31b54', 'restatement', 'The regulator''s decision, while legally sound, was criticized by economists for ignoring broader market implications.', NULL, '[{"id": "d", "text": "No economists ever commented on the regulator''s decision."}, {"id": "b", "text": "The decision was legally invalid and rejected by all economists."}, {"id": "c", "text": "Although the decision was legally valid, economists criticized it for overlooking wider effects on the market."}, {"id": "a", "text": "Economists praised the decision for considering all market implications."}]'::jsonb, 2, '{"strategy": "while legally sound, criticized for ignoring = ניגוד בין חוקיות לביקורת כלכלית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום התגובות שתוארו", "הפוך — סותר ''legally sound''", "נכון! אותה משמעות מדויקת: חוקית, אך נבקרה על התעלמות מהשפעות שוק רחבות", "הפוך — סותר ''criticized by economists for ignoring broader market implications''"]}', 1.37, 1.0, 0.25, 4, 'ai', NULL, true),
('c37c1f80-d65a-41cf-96b6-eaa0bdec729f', 'restatement', 'The author''s latest work, though commercially successful, failed to win over literary critics.', NULL, '[{"id": "b", "text": "The book was both a commercial and critical success."}, {"id": "a", "text": "The book was a commercial failure but loved by critics."}, {"id": "d", "text": "No critics ever reviewed the author''s latest book."}, {"id": "c", "text": "Despite doing well commercially, the book did not impress literary critics."}]'::jsonb, 3, '{"strategy": "though commercially successful, failed with critics = ניגוד בין הצלחה מסחרית לביקורת ספרותית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''failed to win over literary critics''", "הפוך — סותר ''commercially successful''", "סותר את קיום הביקורת שתוארה", "נכון! אותה משמעות מדויקת: הצליחה מסחרית, אך לא כבשה מבקרים ספרותיים"]}', 1.25, 1.0, 0.25, 4, 'ai', NULL, true),
('7acb833d-8a26-4f5b-a3d3-d66ab1443840', 'restatement', 'The company''s expansion plans, though ambitious, were grounded in careful market research.', NULL, '[{"id": "a", "text": "Despite being bold, the expansion plans were based on thorough market analysis."}, {"id": "d", "text": "The company decided against any expansion plans."}, {"id": "b", "text": "The expansion plans were reckless and based on no research at all."}, {"id": "c", "text": "The expansion plans were modest and required no research."}]'::jsonb, 0, '{"strategy": "though ambitious, grounded in careful research = ניגוד בין שאפתנות לביסוס מחקרי.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: שאפתניות, אך מבוססות על מחקר שוק יסודי", "סותר את קיום תוכניות ההתרחבות", "הפוך — סותר ''grounded in careful market research''", "הפוך — סותר ''ambitious''"]}', 1.65, 1.0, 0.25, 4, 'ai', NULL, true),
('b3bc61d7-0e7f-4aae-b52d-ef2b84eb83c0', 'restatement', 'The city''s public transit system, while extensive, suffers from chronic underfunding.', NULL, '[{"id": "c", "text": "The city has no public transit system at all."}, {"id": "b", "text": "Although the transit system covers a wide area, it consistently lacks adequate funding."}, {"id": "d", "text": "The transit system is well funded and has no financial problems."}, {"id": "a", "text": "The transit system is very limited in scope."}]'::jsonb, 1, '{"strategy": "while extensive, suffers from underfunding = ניגוד בין היקף למימון.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום המערכת שתוארה", "נכון! אותה משמעות מדויקת: מערכת נרחבת, אך סובלת ממחסור מתמיד במימון", "הפוך — סותר ''suffers from chronic underfunding''", "הפוך — סותר ''extensive''"]}', 1.87, 1.0, 0.25, 4, 'ai', NULL, true),
('867a7052-c96a-4a30-ab20-ef50b5287831', 'restatement', 'The committee''s findings, though preliminary, point to a troubling pattern of mismanagement.', NULL, '[{"id": "c", "text": "The findings are final and conclusive, not preliminary."}, {"id": "d", "text": "The committee has not yet begun its investigation."}, {"id": "b", "text": "Even though the findings are not yet final, they suggest a concerning pattern of poor management."}, {"id": "a", "text": "The findings show no evidence of any problems."}]'::jsonb, 2, '{"strategy": "though preliminary, point to troubling pattern = ניגוד בין שלב ראשוני למסקנה מטרידה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''though preliminary''", "סותר את קיום הממצאים שתוארו", "נכון! אותה משמעות מדויקת: לא סופיות, אך מצביעות על דפוס מטריד של ניהול כושל", "הפוך — סותר ''a troubling pattern of mismanagement''"]}', 1.11, 1.0, 0.25, 4, 'ai', NULL, true),
('3eec37d1-a808-49ce-ad9e-d28be016d46b', 'restatement', 'The novel''s ending, while satisfying to most readers, left several plot threads unresolved.', NULL, '[{"id": "d", "text": "The ending tied up every single plot thread completely."}, {"id": "a", "text": "The novel had no plot threads to resolve."}, {"id": "b", "text": "The ending was disappointing to all readers."}, {"id": "c", "text": "Although most readers found the ending satisfying, some storylines were left incomplete."}]'::jsonb, 3, '{"strategy": "while satisfying, left threads unresolved = ניגוד בין שביעות רצון לחוסר סגירה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''left several plot threads unresolved''", "סותר את קיום העלילה המורכבת שתוארה", "הפוך — סותר ''satisfying to most readers''", "נכון! אותה משמעות מדויקת: משביעת רצון לרוב הקוראים, אך כמה עלילות נותרו לא פתורות"]}', 1.74, 1.0, 0.25, 4, 'ai', NULL, true),
('2fbc935e-c282-490c-9784-86194ee88f81', 'restatement', 'The startup''s rapid growth, while impressive, has strained its ability to maintain quality control.', NULL, '[{"id": "d", "text": "Despite being impressive, the fast growth has made it difficult to maintain quality standards."}, {"id": "b", "text": "Quality control has improved significantly due to the growth."}, {"id": "c", "text": "The rapid growth has had no effect on quality control."}, {"id": "a", "text": "The startup experienced no growth at all."}]'::jsonb, 0, '{"strategy": "while impressive, strained ability = ניגוד בין הישג לבעיה נלווית.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["נכון! אותה משמעות מדויקת: צמיחה מרשימה, אך הקשתה על שמירת בקרת איכות", "הפוך — סותר ''strained''", "הפוך — סותר ''has strained its ability to maintain quality control''", "סותר ''rapid growth''"]}', 1.35, 1.0, 0.25, 4, 'ai', NULL, true),
('c0c6095d-a2e6-4c40-b37b-0155acef2bdb', 'restatement', 'The museum''s newest exhibit, though controversial, has drawn record attendance numbers.', NULL, '[{"id": "d", "text": "The museum canceled the exhibit due to controversy."}, {"id": "a", "text": "Despite being controversial, the exhibit has brought in an unprecedented number of visitors."}, {"id": "c", "text": "The exhibit was universally praised with no controversy."}, {"id": "b", "text": "The exhibit has attracted very few visitors."}]'::jsonb, 1, '{"strategy": "though controversial, drawn record attendance = ניגוד בין מחלוקת להצלחה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום התערוכה שתוארה", "נכון! אותה משמעות מדויקת: שנויה במחלוקת, אך משכה מספר שיא של מבקרים", "הפוך — סותר ''controversial''", "הפוך — סותר ''drawn record attendance numbers''"]}', 1.8, 1.0, 0.25, 4, 'ai', NULL, true),
('15ab42eb-bfc5-4a75-af64-adaa6839561e', 'restatement', 'The senator''s proposal, while popular with voters, faces significant opposition within her own party.', NULL, '[{"id": "c", "text": "The proposal has no support among voters at all."}, {"id": "b", "text": "The senator withdrew the proposal before any votes were cast."}, {"id": "a", "text": "Although voters like the proposal, it encounters considerable resistance from her own party."}, {"id": "d", "text": "Members of her own party unanimously support the proposal."}]'::jsonb, 2, '{"strategy": "while popular with voters, faces opposition within party = ניגוד בין ציבור למפלגה.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["הפוך — סותר ''popular with voters''", "סותר את קיום ההצעה שתוארה", "נכון! אותה משמעות מדויקת: פופולרית בקרב בוחרים, אך נתקלת בהתנגדות משמעותית במפלגתה", "הפוך — סותר ''faces significant opposition within her own party''"]}', 1.85, 1.0, 0.25, 4, 'ai', NULL, true),
('cad7651d-291c-46a5-a0e1-82fa14027eb1', 'restatement', 'The factory''s new safety measures, though costly to implement, have significantly reduced workplace accidents.', NULL, '[{"id": "d", "text": "The factory decided against implementing any safety measures."}, {"id": "b", "text": "Workplace accidents have increased since the new measures were introduced."}, {"id": "c", "text": "The safety measures were free to implement."}, {"id": "a", "text": "Despite being expensive to put in place, the safety measures have greatly decreased accidents at work."}]'::jsonb, 3, '{"strategy": "though costly, significantly reduced accidents = ניגוד בין עלות לתועלת.", "correct_reason": "אותה משמעות מדויקת.", "options_analysis": ["סותר את קיום האמצעים שתוארו", "הפוך — סותר ''significantly reduced workplace accidents''", "הפוך — סותר ''costly to implement''", "נכון! אותה משמעות מדויקת: יקרות ליישום, אך הפחיתו משמעותית תאונות עבודה"]}', 1.79, 1.0, 0.25, 4, 'ai', NULL, true);